def closedIsland(grid: list[list[int]]) -> int:
    R, C = len(grid), len(grid[0])
    def dfs(r, c):
        if r < 0 or r >= R or c < 0 or c >= C:
            return False
        if grid[r][c] == 1:
            return True
        grid[r][c] = 1
        d1 = dfs(r + 1, c)
        d2 = dfs(r - 1, c)
        d3 = dfs(r, c + 1)
        d4 = dfs(r, c - 1)
        return d1 and d2 and d3 and d4
    ans = 0
    for r in range(R):
        for c in range(C):
            if grid[r][c] == 0:
                if dfs(r, c): ans += 1
    return ans

